class Solution {
    int ans = 0;
    int dfs(int i, int n, vector<int>& cost) {
        if (i > n) return 0;
        int l = dfs(2 * i, n, cost);
        int r = dfs(2 * i + 1, n, cost);
        ans += abs(l - r);
        return cost[i - 1] + max(l, r);
    }
public:
    int minIncrements(int n, vector<int>& cost) {
        dfs(1, n, cost);
        return ans;
    }
};

