class Solution {
    private long ans = 0;
    private long dfs(int i, int n, int[] cost) {
        if (i > n) return 0;
        long l = dfs(2 * i, n, cost);
        long r = dfs(2 * i + 1, n, cost);
        ans += Math.abs(l - r);
        return cost[i - 1] + Math.max(l, r);
    }
    public int minIncrements(int n, int[] cost) {
        dfs(1, n, cost);
        return (int) ans;
    }
}

