class Solution:
    def minIncrements(self, n: int, cost: List[int]) -> int:
        ans = 0
        for i in range(n // 2, 0, -1):
            l, r = cost[2 * i - 1], cost[2 * i]
            ans += abs(l - r)
            cost[i - 1] += max(l, r)
        return ans

